max_time = 10  # seconds

def is_bipartite(adj):
    colors = [-1] * n
    for start in range(n):
        if colors[start] == -1:
            stack = [start]
            colors[start] = 0
            while stack:
                v = stack.pop()
                for nei in adj[v]:
                    if colors[nei] == -1:
                        colors[nei] = 1 - colors[v]
                        stack.append(nei)
                    elif colors[nei] == colors[v]:
                        return False
    return True

def can_color(adj, k=5):
    colors = [-1] * n
    def bt(v):
        if v == n:
            return True
        used = set()
        for nei in adj[v]:
            if colors[nei] != -1:
                used.add(colors[nei])
        for c in range(k):
            if c not in used:
                colors[v] = c
                if bt(v + 1):
                    return True
                colors[v] = -1
        return False
    return bt(0)

